package com.failuredb.failure;
import com.failuredb.repository.FailureRepository; import com.failuredb.user.UserAccount; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="failures")
public class Failure {
 @Id private UUID id; @ManyToOne(optional=false) @JoinColumn(name="repository_id") private FailureRepository repository; @ManyToOne(optional=false) @JoinColumn(name="author_id") private UserAccount author; @Column(nullable=false) private String title; @Column(nullable=false) private String summary; @Lob @Column(name="context_text") private String context; @Lob @Column(name="expected_outcome") private String expectedOutcome; @Lob @Column(name="actual_outcome") private String actualOutcome; @Lob @Column(name="root_cause") private String rootCause; @Lob @Column(name="warning_signs") private String warningSigns; @Lob @Column(name="lessons_learned") private String lessonsLearned; @Lob private String prevention; @Column(nullable=false) private int severity; @Column(nullable=false) private String status; private String tags; @Column(name="occurred_year") private Integer occurredYear; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 protected Failure(){} public Failure(FailureRepository repository,UserAccount author,String title,String summary,String context,String expectedOutcome,String actualOutcome,String rootCause,String warningSigns,String lessonsLearned,String prevention,int severity,String tags,Integer occurredYear){this.id=UUID.randomUUID();this.repository=repository;this.author=author;this.title=title;this.summary=summary;this.context=context;this.expectedOutcome=expectedOutcome;this.actualOutcome=actualOutcome;this.rootCause=rootCause;this.warningSigns=warningSigns;this.lessonsLearned=lessonsLearned;this.prevention=prevention;this.severity=severity;this.status="PUBLISHED";this.tags=tags;this.occurredYear=occurredYear;this.createdAt=Instant.now();this.updatedAt=this.createdAt;}
 public UUID getId(){return id;} public FailureRepository getRepository(){return repository;} public UserAccount getAuthor(){return author;} public String getTitle(){return title;} public String getSummary(){return summary;} public String getContext(){return context;} public String getExpectedOutcome(){return expectedOutcome;} public String getActualOutcome(){return actualOutcome;} public String getRootCause(){return rootCause;} public String getWarningSigns(){return warningSigns;} public String getLessonsLearned(){return lessonsLearned;} public String getPrevention(){return prevention;} public int getSeverity(){return severity;} public String getStatus(){return status;} public String getTags(){return tags;} public Integer getOccurredYear(){return occurredYear;} public Instant getCreatedAt(){return createdAt;}
}
